1	import { useMutation } from "@tanstack/react-query";
2	import { toast } from "sonner";
3	import supabase from "@/lib/supabase";
4	import { useAuth } from "@/contexts/AuthContext";
5	import type { PlanType } from "@/types";
6	
7	// ── useCheckout ──────────────────────────────────────────────────
8	// Initiates a Dodo Payments subscription checkout session for the given
9	// plan + billing cycle. On success, redirects to Dodo-hosted checkout.
10	
11	export function useCheckout() {
12	  return useMutation({
13	    mutationFn: async ({
14	      plan,
15	      billingCycle,
16	    }: {
17	      plan: Exclude<PlanType, "free">;
18	      billingCycle: "monthly" | "annual";
19	    }) => {
20	      const { data, error } = await supabase.functions.invoke(
21	        "dodo-checkout",
22	        {
23	          body: { plan, billing_cycle: billingCycle },
24	        }
25	      );
26	
27	      if (error) {
28	        throw new Error(
29	          error.message || "Failed to start checkout. Please try again."
30	        );
31	      }
32	
33	      if (!data?.url) {
34	        throw new Error("No checkout URL returned from server.");
35	      }
36	
37	      return data.url as string;
38	    },
39	    onSuccess: (url) => {
40	      window.location.href = url;
41	    },
42	    onError: (error: unknown) => {
43	      const message =
44	        error instanceof Error ? error.message : "Checkout failed.";
45	      toast.error(message);
46	    },
47	  });
48	}
49	
50	// ── useCustomerPortal ────────────────────────────────────────────
51	// Opens the Dodo Payments Customer Portal so users can manage their
52	// subscription, payment method, and invoices.
53	
54	export function useCustomerPortal() {
55	  return useMutation({
56	    mutationFn: async () => {
57	      const { data, error } = await supabase.functions.invoke("dodo-portal");
58	
59	      if (error) {
60	        throw new Error(
61	          error.message || "Failed to open billing portal. Please try again."
62	        );
63	      }
64	
65	      if (!data?.url) {
66	        throw new Error("No portal URL returned from server.");
67	      }
68	
69	      return data.url as string;
70	    },
71	    onSuccess: (url) => {
72	      window.location.href = url;
73	    },
74	    onError: (error: unknown) => {
75	      const message =
76	        error instanceof Error ? error.message : "Failed to open portal.";
77	      toast.error(message);
78	    },
79	  });
80	}
81	
82	// ── useUsage ─────────────────────────────────────────────────────
83	// Returns current scan usage derived from the authenticated user's profile.
84	// No network call — reads from AuthContext which is kept fresh.
85	
86	export function useUsage() {
87	  const { profile } = useAuth();
88	
89	  if (!profile) {
90	    return {
91	      scansUsed: 0,
92	      scanLimit: 0,
93	      usagePercent: 0,
94	      plan: "free" as PlanType,
95	      billingCycleEnd: null as string | null,
96	    };
97	  }
98	
99	  const usagePercent =
100	    profile.scan_limit > 0
101	      ? Math.min((profile.scans_used / profile.scan_limit) * 100, 100)
102	      : 0;
103	
104	  return {
105	    scansUsed: profile.scans_used,
106	    scanLimit: profile.scan_limit,
107	    usagePercent,
108	    plan: profile.plan,
109	    billingCycleEnd: profile.billing_cycle_end ?? null,
110	  };
111	}
