53	/** Normalize URL: prepend https:// if missing */
54	function normalizeUrl(str: string): string {
55	  const trimmed = str.trim();
56	  if (!trimmed) return trimmed;
57	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
58	  return `https://${trimmed}`;
59	}
