81	function scoreToRange(score: number): string {
82	  if (score <= 20) return "0-20";
83	  if (score <= 40) return "21-40";
84	  if (score <= 60) return "41-60";
85	  if (score <= 80) return "61-80";
86	  return "81-100";
87	}
