96	    page_type: row.page_type,
97	    status: row.status,
98	    overall_score: row.overall_score,
99	    issues_found: row.issues_found,
100	    critical_issues: row.critical_issues,
101	    warnings: row.warnings,
102	    quick_wins: row.quick_wins,
103	    screenshot_url: row.screenshot_url,
