110	// ── useDashboardStats ───────────────────────────────────────────
111	
112	export function useDashboardStats() {
113	  const { user } = useAuth();
114	
115	  return useQuery({
116	    queryKey: ["dashboard-stats", user?.id ?? ""],
117	    queryFn: async (): Promise<DashboardData> => {
118	      if (!user?.id) return EMPTY_DASHBOARD;
119	
120	      // Fetch all completed scans for the user
121	      const { data: scansData, error: scansError } = await supabase
122	        .from("scans")
123	        .select("*")
124	        .eq("user_id", user.id)
125	        .order("created_at", { ascending: false });
126	
127	      if (scansError) throw new Error(scansError.message);
128	
129	      const scans = (scansData as ScanRow[]).map(rowToScan);
130	
131	      if (scans.length === 0) return EMPTY_DASHBOARD;
132	
133	      const completedScans = scans.filter((s) => s.status === "completed" && s.overall_score !== null);
134	      const recentScans = scans.slice(0, 5);
135	      const latestScanId = completedScans[0]?.id ?? null;
136	
137	      // ── Stats aggregation ─────────────────────────────────────
138	
139	      const now = new Date();
140	      const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
141	      const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
142	
143	      const scansThisMonth = completedScans.filter(
144	        (s) => new Date(s.created_at) >= monthStart
145	      );
146	      const scansLastMonth = completedScans.filter(
147	        (s) =>
148	          new Date(s.created_at) >= lastMonthStart &&
149	          new Date(s.created_at) < monthStart
150	      );
151	
152	      const avgScore =
153	        completedScans.length > 0
154	          ? Math.round(
155	              completedScans.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
156	                completedScans.length
157	            )
158	          : 0;
159	
160	      const avgScoreThisMonth =
161	        scansThisMonth.length > 0
162	          ? Math.round(
163	              scansThisMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
164	                scansThisMonth.length
165	            )
166	          : 0;
167	
168	      const avgScoreLastMonth =
169	        scansLastMonth.length > 0
170	          ? Math.round(
171	              scansLastMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
172	                scansLastMonth.length
173	            )
174	          : 0;
175	
176	      const totalIssues = completedScans.reduce((sum, s) => sum + s.issues_found, 0);
177	      const totalCritical = completedScans.reduce((sum, s) => sum + s.critical_issues, 0);
178	      const totalQuickWins = completedScans.reduce((sum, s) => sum + s.quick_wins, 0);
179	
180	      const scoreTrendDelta =
181	        avgScoreLastMonth > 0 ? avgScoreThisMonth - avgScoreLastMonth : 0;
182	      const scansTrendDelta =
183	        scansLastMonth.length > 0
184	          ? Math.round(
185	              ((scansThisMonth.length - scansLastMonth.length) /
186	                scansLastMonth.length) *
187	                100
188	            )
189	          : scansThisMonth.length > 0
190	          ? 100
191	          : 0;
192	
193	      const stats: DashboardStats = {
194	        total_scans: scansThisMonth.length,
195	        avg_score: avgScore,
196	        total_issues: totalIssues,
197	        critical_issues: totalCritical,
198	        estimated_revenue_impact: Math.round(totalQuickWins * 125),
199	        score_trend: scoreTrendDelta,
200	        scans_trend: scansTrendDelta,
201	        quick_wins: totalQuickWins,
202	      };
203	
204	      // ── Score Trend (last 4 weeks) ────────────────────────────
205	
206	      const fourWeeksAgo = new Date(now.getTime() - 28 * 24 * 60 * 60 * 1000);
207	      const recentForTrend = completedScans.filter(
208	        (s) => new Date(s.created_at) >= fourWeeksAgo
209	      );
210	
211	      const weekBuckets = new Map<number, number[]>(); // weekIndex → scores[]
212	      for (const scan of recentForTrend) {
213	        const scanDate = new Date(scan.created_at);
214	        const diffMs = now.getTime() - scanDate.getTime();
215	        const weekIndex = 3 - Math.min(3, Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7)));
216	        const existing = weekBuckets.get(weekIndex) ?? [];
217	        if (scan.overall_score !== null) {
218	          existing.push(scan.overall_score);
219	          weekBuckets.set(weekIndex, existing);
220	        }
221	      }
222	
223	      const scoreTrend: ScoreTrendPoint[] = [3, 2, 1, 0].map((weeksAgo, idx) => {
224	        const label = getWeekLabelForIndex(weeksAgo);
225	        const scores = weekBuckets.get(idx) ?? [];
226	        const avg =
227	          scores.length > 0
228	            ? Math.round(scores.reduce((s, v) => s + v, 0) / scores.length)
229	            : 0;
230	        return { week: label, score: avg };
231	      }).filter((p) => p.score > 0);
232	
233	      // ── Score Distribution ────────────────────────────────────
234	
235	      const RANGES = ["0-20", "21-40", "41-60", "61-80", "81-100"];
236	      const distributionMap = new Map<string, number>(RANGES.map((r) => [r, 0]));
237	
238	      for (const scan of completedScans) {
239	        if (scan.overall_score !== null) {
240	          const bucket = scoreToRange(scan.overall_score);
241	          distributionMap.set(bucket, (distributionMap.get(bucket) ?? 0) + 1);
242	        }
243	      }
244	
245	      const scoreDistribution: ScoreDistributionBucket[] = RANGES.map((range) => ({
246	        range,
247	        count: distributionMap.get(range) ?? 0,
248	        fill: getBucketFill(range),
249	      }));
250	
251	      // ── Top Quick Wins from latest completed scan ─────────────
252	
253	      let topQuickWins: (Finding & { pillar: string })[] = [];
254	
255	      if (latestScanId) {
256	        const { data: resultsData } = await supabase
257	          .from("scan_results")
258	          .select("*")
259	          .eq("scan_id", latestScanId);
260	
261	        if (resultsData && resultsData.length > 0) {
262	          const allFindings: (Finding & { pillar: string })[] = (
263	            resultsData as ScanResultRow[]
264	          ).flatMap((r) =>
265	            (r.findings ?? [])
266	              .filter((f: DbFinding) => f.severity !== "passed" && f.effort === "quick")
267	              .map((f: DbFinding) => ({
268	                id: f.id,
269	                title: f.title,
270	                severity: f.severity,
271	                current_state: f.current_state,
272	                recommendation: f.recommendation,
273	                ai_suggestion: f.ai_suggestion,
274	                is_premium: f.is_premium,
275	                effort: f.effort,
276	                estimated_lift: f.estimated_lift,
277	                category: f.category,
278	                pillar: r.pillar,
279	              }))
280	          );
281	
282	          topQuickWins = allFindings
283	            .sort((a, b) => {
284	              const liftA = parseFloat(a.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
285	              const liftB = parseFloat(b.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
286	              return liftB - liftA;
287	            })
288	            .slice(0, 3);
289	        }
290	      }
291	
292	      return {
293	        stats,
294	        recentScans,
295	        scoreTrend,
296	        scoreDistribution,
297	        topQuickWins,
298	        latestScanId,
299	      };
300	    },
301	    enabled: !!user?.id,
302	    staleTime: 1000 * 60 * 2, // 2 minutes
303	  });
304	}
