128	      const textarea = document.createElement("textarea");
129	      textarea.value = text;
130	      document.body.appendChild(textarea);
131	      textarea.select();
132	      document.execCommand("copy");
133	      document.body.removeChild(textarea);
134	    }
135	    setCopied(true);
136	    timerRef.current = setTimeout(() => setCopied(false), 2000);
137	  };
138	
139	  return (
140	    <TooltipProvider delayDuration={200}>
141	      <Tooltip>
142	        <TooltipTrigger asChild>
143	          <button
144	            onClick={handleCopy}
145	            className={cn(
